#!/usr/bin/env python3
"""Turn the Labspace instructions into a bash script running the lab as a learner would.

Every code block of the sections listed in labspace/labspace.yaml is processed in order:

- `bash` blocks are executed in ~/project and must succeed, except:
  - blocks with the `no-run-button` metadata are skipped (not meant to be run),
  - blocks needing a Docker account (`docker login`, `docker compose up --build`) are skipped,
  - blocks directly followed by a `none` block starting with `Error:` must fail,
    and their output must contain that documented error message.
- blocks with the `save-as=<path>` metadata are saved to ~/project/<path>, like the "Save file" button.

At the end, the script checks that every :fileLink[] path exists in ~/project.

Usage: python3 lab-to-script.py [labspace-dir] > lab.sh
"""
import base64
import os
import re
import sys

sys.stdout.reconfigure(encoding="utf-8", newline="\n")

LABSPACE_DIR = sys.argv[1] if len(sys.argv) > 1 else "labspace"
SKIP_PATTERNS = ["docker login", "docker compose up --build"]

FENCE = re.compile(r"^```(\w*)([^\n]*)\n(.*?)^```", re.S | re.M)
FILE_LINK = re.compile(r':fileLink\[[^\]]*\]\{path="([^"]+)"')


def b64(text):
    return base64.b64encode(text.encode()).decode()


def sections():
    with open(os.path.join(LABSPACE_DIR, "labspace.yaml"), encoding="utf-8") as f:
        return re.findall(r"contentPath:\s*(\S+)", f.read())


def steps():
    for section in sections():
        with open(os.path.join(LABSPACE_DIR, section), encoding="utf-8") as f:
            content = f.read()
        blocks = list(FENCE.finditer(content))
        for i, block in enumerate(blocks):
            lang, meta, body = block.group(1), block.group(2).split(), block.group(3)
            line = content.count("\n", 0, block.start()) + 1
            label = f"{section}:{line}"

            save_as = next((m.split("=", 1)[1] for m in meta if m.startswith("save-as=")), None)
            if save_as:
                yield "save", label, save_as, body
            if lang != "bash":
                continue

            if "no-run-button" in meta or any(p in body for p in SKIP_PATTERNS):
                yield "skip", label, "", body
                continue

            following = blocks[i + 1] if i + 1 < len(blocks) else None
            if (
                following is not None
                and following.group(1) == "none"
                and following.group(3).startswith("Error:")
                and "```" not in content[block.end():following.start()]
            ):
                yield "fail", label, following.group(3).splitlines()[0], body
            else:
                yield "run", label, "", body


def file_links():
    links = []
    for section in sections():
        with open(os.path.join(LABSPACE_DIR, section), encoding="utf-8") as f:
            links += FILE_LINK.findall(f.read())
    return sorted(set(links))


print(r'''#!/bin/bash
# Generated by .github/scripts/lab-to-script.py, do not edit.
exec 2>&1
cd ~/project
FAILURES=0

step() {
  local mode=$1 label=$2 arg=$(echo "$3" | base64 -d) body=$(echo "$4" | base64 -d)
  if [ "$mode" = "save" ]; then
    echo "💾 $label: save as $arg"
    mkdir -p "$(dirname "$arg")" && printf '%s\n' "$body" > "$arg"
    return
  fi
  if [ "$mode" = "skip" ]; then
    echo "⏭️  $label: skipped"
    echo "$body" | sed 's/^/    /'
    return
  fi
  echo "::group::▶️  $label"
  echo "$body" | sed 's/^/$ /'
  printf '%s\n' "$body" > /tmp/step.sh
  timeout 600 bash -eo pipefail /tmp/step.sh > /tmp/step.out 2>&1
  local rc=$?
  cat /tmp/step.out
  echo "::endgroup::"
  if [ "$mode" = "run" ] && [ $rc -ne 0 ]; then
    echo "::error title=Lab step failed::$label exited with code $rc"
    FAILURES=$((FAILURES + 1))
  elif [ "$mode" = "fail" ] && [ $rc -eq 0 ]; then
    echo "::error title=Lab step should fail::$label was expected to fail with: $arg"
    FAILURES=$((FAILURES + 1))
  elif [ "$mode" = "fail" ] && ! grep -qF -- "$arg" /tmp/step.out; then
    echo "::error title=Unexpected error message::$label did not output the documented error: $arg"
    FAILURES=$((FAILURES + 1))
  else
    echo "✅ $label"
  fi
}

check_file_link() {
  if [ -e "$1" ]; then
    echo "✅ fileLink $1"
  else
    echo "::error title=Broken fileLink::$1 does not exist in the project"
    FAILURES=$((FAILURES + 1))
  fi
}
''')

for mode, label, arg, body in steps():
    print(f"step {mode} '{label}' '{b64(arg)}' '{b64(body)}'")

print('\necho "::group::Checking fileLink paths"')
for path in file_links():
    print(f"check_file_link '{path}'")
print('echo "::endgroup::"')

print(r'''
if [ $FAILURES -ne 0 ]; then
  echo "::error::$FAILURES lab check(s) failed"
  exit 1
fi
echo "🎉 All lab steps passed"''')
